+import { useState } from "react";
+
+import { useStudio } from "../../state/StudioContext";
+import type { Observation, ObservationKind } from "../../types";
+
+const KIND_LABELS: Record<ObservationKind, string> = {
+  career: "Your career",
+  opportunity: "The opportunity",
+  business: "The business",
+  stakeholder: "The people",
+  constraint: "The constraints",
+  evidence: "The evidence",
+  preference: "How you like to work",
+};
+
+const KIND_ORDER: ObservationKind[] = [
+  "opportunity",
+  "career",
+  "business",
+  "stakeholder",
+  "constraint",
+  "evidence",
+  "preference",
+];
+
+function groupByKind(observations: Observation[]): Array<[ObservationKind, Observation[]]> {
+  const groups: Array<[ObservationKind, Observation[]]> = [];
+  for (const kind of KIND_ORDER) {
+    const items = observations.filter((observation) => observation.kind === kind);
+    if (items.length > 0) {
+      groups.push([kind, items]);
+    }
+  }
+  return groups;
+}
+
+function confidenceLabel(confidence: number | null): string | null {
+  if (confidence == null) {
+    return null;
+  }
+  return `${Math.round(confidence * 100)}% sure`;
+}
+
+export function MemoryPanel() {
+  const {
+    memory,
+    memoryLoading,
+    refreshMemory,
+    addObservation,
+    updateObservation,
+    clearMemory,
+  } = useStudio();
+  const [editingId, setEditingId] = useState<string | null>(null);
+  const [draft, setDraft] = useState("");
+  const [newKind, setNewKind] = useState<ObservationKind>("career");
+  const [newText, setNewText] = useState("");
+  const [adding, setAdding] = useState(false);
+  const [confirmingClear, setConfirmingClear] = useState(false);
+
+  const confirmed = memory.filter((observation) => observation.status === "confirmed");
+  const suggested = memory.filter((observation) => observation.status === "suggested");
+  const visible = [...confirmed, ...suggested];
+
+  function beginEdit(observation: Observation) {
+    setEditingId(observation.id);
+    setDraft(observation.text);
+  }
+
+  async function saveEdit(observationId: string) {
+    if (!draft.trim()) {
+      return;
+    }
+    await updateObservation(observationId, { text: draft.trim() });
+    setEditingId(null);
+  }
+
+  async function submitNew(event: React.FormEvent) {
+    event.preventDefault();
+    if (!newText.trim() || adding) {
+      return;
+    }
+    setAdding(true);
+    const saved = await addObservation({ kind: newKind, text: newText.trim() });
+    if (saved) {
+      setNewText("");
+    }
+    setAdding(false);
+  }
+
+  async function forgetEverything() {
+    await clearMemory();
+    setConfirmingClear(false);
+  }
+
+  return (
+    <section className="fade-in memory-panel">
+      <div className="memory-panel__head">
+        <div>
+          <h2 className="section-title">What I've learned</h2>
+          <p className="caption">
+            The context I'm carrying for you. Correct me, and I'll use the correction next time.
+          </p>
+        </div>
+        <button
+          type="button"
+          className="studio-button studio-button--ghost"
+          onClick={() => void refreshMemory()}
+          disabled={memoryLoading}
+        >
+          {memoryLoading ? "Checking…" : "Refresh"}
+        </button>
+      </div>
+
+      {visible.length === 0 ? (
+        <div className="studio-card memory-panel__empty">
+          <p>I haven't learned anything yet.</p>
+          <p className="caption">
+            Tell me what you're trying to make happen, or add something below. I'll ask before I
+            treat it as true.
+          </p>
+        </div>
+      ) : (
+        groupByKind(visible).map(([kind, items]) => (
+          <div className="memory-panel__group" key={kind}>
+            <h3 className="memory-panel__kind">{KIND_LABELS[kind]}</h3>
+            <ul className="memory-panel__list">
+              {items.map((observation) => (
+                <li className="memory-item" key={observation.id}>
+                  <div className="memory-item__body">
+                    {editingId === observation.id ? (
+                      <textarea
+                        className="studio-input memory-item__edit"
+                        aria-label="Edit what I've learned"
+                        value={draft}
+                        onChange={(event) => setDraft(event.target.value)}
+                      />
+                    ) : (
+                      <p className="memory-item__text">{observation.text}</p>
+                    )}
+                    <div className="memory-item__meta">
+                      <span
+                        className={`memory-item__status memory-item__status--${observation.status}`}
+                      >
+                        {observation.status === "confirmed" ? "You confirmed this" : "Still checking"}
+                      </span>
+                      {confidenceLabel(observation.confidence) ? (
+                        <span className="memory-item__confidence">
+                          {confidenceLabel(observation.confidence)}
+                        </span>
+                      ) : null}
+                    </div>
+                  </div>
+
+                  <div className="memory-item__actions">
+                    {editingId === observation.id ? (
+                      <>
+                        <button
+                          type="button"
+                          className="studio-button"
+                          onClick={() => void saveEdit(observation.id)}
+                        >
+                          Save
+                        </button>
+                        <button
+                          type="button"
+                          className="studio-button studio-button--ghost"
+                          onClick={() => setEditingId(null)}
+                        >
+                          Cancel
+                        </button>
+                      </>
+                    ) : (
+                      <>
+                        {observation.status === "suggested" ? (
+                          <button
+                            type="button"
+                            className="studio-button"
+                            onClick={() =>
+                              void updateObservation(observation.id, { status: "confirmed" })
+                            }
+                          >
+                            That's right
+                          </button>
+                        ) : null}
+                        <button
+                          type="button"
+                          className="studio-button studio-button--ghost"
+                          onClick={() => beginEdit(observation)}
+                        >
+                          Edit
+                        </button>
+                        <button
+                          type="button"
+                          className="studio-button studio-button--ghost"
+                          onClick={() =>
+                            void updateObservation(observation.id, { status: "dismissed" })
+                          }
+                        >
+                          Not quite
+                        </button>
+                      </>
+                    )}
+                  </div>
+                </li>
+              ))}
+            </ul>
+          </div>
+        ))
+      )}
+
+      <form className="studio-card memory-panel__add" onSubmit={submitNew}>
+        <h3 className="memory-panel__kind">Add something I should know</h3>
+        <div className="memory-panel__add-row">
+          <select
+            className="studio-select"
+            aria-label="What kind of context is this?"
+            value={newKind}
+            onChange={(event) => setNewKind(event.target.value as ObservationKind)}
+          >
+            {KIND_ORDER.map((kind) => (
+              <option key={kind} value={kind}>
+                {KIND_LABELS[kind]}
+              </option>
+            ))}
+          </select>
+          <input
+            className="studio-input"
+            aria-label="What should I know?"
+            placeholder="The thing I should not have to repeat."
+            value={newText}
+            onChange={(event) => setNewText(event.target.value)}
+          />
+          <button type="submit" className="studio-button" disabled={adding || !newText.trim()}>
+            {adding ? "Saving…" : "Add"}
+          </button>
+        </div>
+      </form>
+
+      <div className="memory-panel__danger">
+        {confirmingClear ? (
+          <>
+            <span>This removes every conversation and observation on this machine.</span>
+            <button type="button" className="studio-button" onClick={() => void forgetEverything()}>
+              Yes, forget it all
+            </button>
+            <button
+              type="button"
+              className="studio-button studio-button--ghost"
+              onClick={() => setConfirmingClear(false)}
+            >
+              Keep it
+            </button>
+          </>
+        ) : (
+          <button
+            type="button"
+            className="studio-button studio-button--ghost"
+            onClick={() => setConfirmingClear(true)}
+          >
+            Forget everything
+          </button>
+        )}
+      </div>
+    </section>
+  );
+}

